(581, 1, '2026-05-11 08:16:21', '0000-00-00 00:00:00', '{\n    \"astra-settings[header-desktop-items]\": {\n        \"value\": {\n            \"popup\": {\n                \"popup_content\": [\n                    \"mobile-menu\"\n                ]\n            },\n            \"above\": {\n                \"above_left\": [],\n                \"above_left_center\": [],\n                \"above_center\": [],\n                \"above_right_center\": [],\n                \"above_right\": []\n            },\n            \"primary\": {\n                \"primary_left\": [\n                    \"logo\"\n                ],\n                \"primary_left_center\": [],\n                \"primary_center\": [],\n                \"primary_right_center\": [],\n                \"primary_right\": [\n                    \"menu-1\",\n                    \"social-icons-1\"\n                ]\n            },\n            \"below\": {\n                \"below_left\": [],\n                \"below_left_center\": [],\n                \"below_center\": [],\n                \"below_right_center\": [],\n                \"below_right\": []\n            },\n            \"flag\": true\n        },\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-05-11 08:16:21\"\n    },\n    \"astra-settings[header-preset-style]\": {\n        \"value\": \"preset_1\",\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-05-11 08:16:21\"\n    },\n    \"astra-settings[header-mobile-items]\": {\n        \"value\": {\n            \"popup\": {\n                \"popup_content\": [\n                    \"mobile-menu\",\n                    \"social-icons-1\"\n                ]\n            },\n            \"above\": {\n                \"above_left\": [],\n                \"above_center\": [],\n                \"above_right\": []\n            },\n            \"primary\": {\n                \"primary_left\": [\n                    \"