INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(688, 1, '2026-05-14 13:44:45', '2026-05-14 13:44:45', '{\n    \"custom_css[astra]\": {\n        \"value\": \"/* \\u00c9p n\\u00fat v\\u00e0 \\u00f4 nh\\u1eadp kh\\u00f4ng \\u0111\\u01b0\\u1ee3c xu\\u1ed1ng d\\u00f2ng */\\n.wp-block-search__inside-wrapper {\\n    display: flex !important;\\n    flex-wrap: nowrap !important; /* Tuy\\u1ec7t \\u0111\\u1ed1i kh\\u00f4ng cho xu\\u1ed1ng d\\u00f2ng */\\n    align-items: stretch !important;\\n}\\n\\n/* N\\u1edbi r\\u1ed9ng n\\u00fat m\\u1ed9t ch\\u00fat \\u0111\\u1ec3 ch\\u1eef kh\\u00f4ng b\\u1ecb \\u0111\\u1ee9ng h\\u00ecnh */\\n.wp-block-search__button {\\n    white-space: nowrap !important; /* Ch\\u1eef ph\\u1ea3i n\\u1eb1m tr\\u00ean 1 h\\u00e0ng */\\n    min-width: 60px !important;    /* \\u0110\\u1ed9 r\\u1ed9ng t\\u1ed1i thi\\u1ec3u cho n\\u00fat */\\n    padding: 0 15px !important;\\n}\\n\\n/* Ch\\u1ec9nh l\\u1ea1i \\u00f4 nh\\u1eadp cho c\\u00e2n \\u0111\\u1ed1i */\\n.wp-block-search__input {\\n    flex-grow: 1 !important;\\n    min-width: 0 !important; /* \\u0110\\u1ec3 n\\u00f3 kh\\u00f4ng \\u0111\\u1ea9y n\\u00fat ra ngo\\u00e0i */\\n}\\n/* 1. \\u00c9p chi\\u1ec1u cao c\\u1ed1 \\u0111\\u1ecbnh cho khung s\\u1ea3n ph\\u1ea9m */\\n.woocommerce ul.products li.product {\\n    display: flex;\\n    flex-direction: column;\\n    background: #fff;\\n    padding: 15px;\\n    border: 1px solid #eee;\\n    border-radius: 8px;\\n    height: 100%;\\n}\\n\\n/* 2. \\u00c9p \\u1ea3nh s\\u1ea3n ph\\u1ea9m b\\u1eb1ng nhau v\\u00e0 kh\\u00f4ng b\\u1ecb m\\u00e9o */\\n.woocommerce ul.products li.product img {\\n    height: 200px !important; /* B\\u1ea1n c\\u00f3 th\\u1ec3 ch\\u1ec9nh s\\u1ed1 n\\u00e0y t\\u00f9y \\u00fd */\\n    object-fit: contain !important; \\n    margin-bottom: 15px;\\n}\\n\\n/* 3. \\u00c9p t\\u00ean s\\u1ea3n ph\\u1ea9m lu\\u00f4n chi\\u1ebfm 2 d\\u00f2ng (\\u0111\\u1ec3 kh\\u00f4ng b\\u1ecb l\\u1ec7ch gi\\u00e1) */\\n.woocommerce ul.products li.product .woocommerce-loop-product__title {\\n    min-height: 40px; \\n    line-height: 20px;\\n    margin-bottom: 10px;\\n    display: -webkit-box;\\n    -webkit-line-clamp: 2;\\n    -webkit-box-orient: vertical;\\n    overflow: hidden;\\n}\\n\\n/* 4. \\u0110\\u1ea9y n\\u00fat Add to cart xu\\u1ed1ng t\\u1eadn c\\u00f9ng cho th\\u1eb3ng h\\u00e0ng */\\n.woocommerce ul.products li.product .button {\\n    margin-top: auto !important;\\n    align-self: center;\\n}\\n/* \\u00c9p thanh ch\\u1ee9a logo gi\\u00e3n s\\u00e1t l\\u1ec1 tr\\u00e1i m\\u00e0n h\\u00ecnh */\\n.site-header .ast-container {\\n    max-width: 100% !important;\\n    padding-left: 15px !important;\\n}\\n.main-header-bar-wrap {\\n    max-width: 100% !important;\\n}\\n/* 1. \\u00c9p thanh Header m\\u00e0u xanh tr\\u00e0n r\\u1ed9ng ra s\\u00e1t m\\u00e9p */\\n.site-header .ast-container, \\n.main-header-bar-wrap,\\n.ast-main-header-wrap {\\n    max-width: 96% !important;\\n    width: 96% !important;\\n    margin-left: auto !important;\\n    margin-right: auto !important;\\n    padding-left: 0 !important;\\n    padding-right: 0 !important;\\n}\\n\\n/* 2. \\u00c9p ph\\u1ea7n th\\u00e2n trang (ch\\u1ee9a slide) ph\\u00e1 v\\u1ee1 khung gi\\u1edbi h\\u1ea1n m\\u1eb7c \\u0111\\u1ecbnh */\\n.home .site-content .ast-container {\\n    max-width: 96% !important;\\n    width: 96% !important;\\n    padding-left: 0 !important;\\n    padding-right: 0 !important;\\n    margin-left: auto !important;\\n    margin-right: auto !important;\\n}\\n\\n/* 3. \\u00c9p c\\u00e1c kh\\u1ed1i Elementor b\\u00ean trong gi\\u00e3n theo chi\\u1ec1u r\\u1ed9ng m\\u1edbi */\\n.site-content #primary,\\n.elementor-section, \\n.elementor-container,\\n.e-con {\\n    max-width: 100% !important;\\n    width: 100% !important;\\n}\\n\\n\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-05-14 13:44:26\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '0ecc4d0e-0444-406e-9aa4-376356cedc17', '', '', '2026-05-14 13:44:45', '2026-05-14 13:44:45', '', 0, 'http://localhost/BTL/?p=688', 0, 'customize_changeset', '', 0),
(689, 1, '2026-05-14 13:44:45', '2026-05-14 13:44:45', '/* Ép nút và ô nhập không được xuống dòng */\n.wp-block-search__inside-wrapper {\n    display: flex !important;\n    flex-wrap: nowrap !important; /* Tuyệt đối không cho xuống dòng */\n    align-items: stretch !important;\n}\n\n/* Nới rộng nút một chút để chữ không bị đứng hình */\n.wp-block-search__button {\n    white-space: nowrap !important; /* Chữ phải nằm trên 1 hàng */\n    min-width: 60px !important;    /* Độ rộng tối thiểu cho nút */\n    padding: 0 15px !important;\n}\n\n/* Chỉnh lại ô nhập cho cân đối */\n.wp-block-search__input {\n    flex-grow: 1 !important;\n    min-width: 0 !important; /* Để nó không đẩy nút ra ngoài */\n}\n/* 1. Ép chiều cao cố định cho khung sản phẩm */\n.woocommerce ul.products li.product {\n    display: flex;\n    flex-direction: column;\n    background: #fff;\n    padding: 15px;\n    border: 1px solid #eee;\n    border-radius: 8px;\n    height: 100%;\n}\n\n/* 2. Ép ảnh sản phẩm bằng nhau và không bị méo */\n.woocommerce ul.products li.product img {\n    height: 200px !important; /* Bạn có thể chỉnh số này tùy ý */\n    object-fit: contain !important; \n    margin-bottom: 15px;\n}\n\n/* 3. Ép tên sản phẩm luôn chiếm 2 dòng (để không bị lệch giá) */\n.woocommerce ul.products li.product .woocommerce-loop-product__title {\n    min-height: 40px; \n    line-height: 20px;\n    margin-bottom: 10px;\n    display: -webkit-box;\n    -webkit-line-clamp: 2;\n    -webkit-box-orient: vertical;\n    overflow: hidden;\n}\n\n/* 4. Đẩy nút Add to cart xuống tận cùng cho thẳng hàng */\n.woocommerce ul.products li.product .button {\n    margin-top: auto !important;\n    align-self: center;\n}\n/* Ép thanh chứa logo giãn sát lề trái màn hình */\n.site-header .ast-container {\n    max-width: 100% !important;\n    padding-left: 15px !important;\n}\n.main-header-bar-wrap {\n    max-width: 100% !important;\n}\n/* 1. Ép thanh Header màu xanh tràn rộng ra sát mép */\n.site-header .ast-container, \n.main-header-bar-wrap,\n.ast-main-header-wrap {\n    max-width: 96% !important;\n    width: 96% !important;\n    margin-left: auto !important;\n    margin-right: auto !important;\n    padding-left: 0 !important;\n    padding-right: 0 !important;\n}\n\n/* 2. Ép phần thân trang (chứa slide) phá vỡ khung giới hạn mặc định */\n.home .site-content .ast-container {\n    max-width: 96% !important;\n    width: 96% !important;\n    padding-left: 0 !important;\n    padding-right: 0 !important;\n    margin-left: auto !important;\n    margin-right: auto !important;\n}\n\n/* 3. Ép các khối Elementor bên trong giãn theo chiều rộng mới */\n.site-content #primary,\n.elementor-section, \n.elementor-container,\n.e-con {\n    max-width: 100% !important;\n    width: 100% !important;\n}\n\n', 'astra', '', 'inherit', 'closed', 'closed', '', '583-revision-v1', '', '', '2026-05-14 13:44:45', '2026-05-14 13:44:45', '', 583, 'http://localhost/BTL/?p=689', 0, 'revision', '', 0),
(690, 1, '2026-05-14 13:45:11', '2026-05-14 13:45:11', '{\n    \"custom_css[astra]\": {\n        \"value\": \"/* \\u00c9p n\\u00fat v\\u00e0 \\u00f4 nh\\u1eadp kh\\u00f4ng \\u0111\\u01b0\\u1ee3c xu\\u1ed1ng d\\u00f2ng */\\n.wp-block-search__inside-wrapper {\\n    display: flex !important;\\n    flex-wrap: nowrap !important; /* Tuy\\u1ec7t \\u0111\\u1ed1i kh\\u00f4ng cho xu\\u1ed1ng d\\u00f2ng */\\n    align-items: stretch !important;\\n}\\n\\n/* N\\u1edbi r\\u1ed9ng n\\u00fat m\\u1ed9t ch\\u00fat \\u0111\\u1ec3 ch\\u1eef kh\\u00f4ng b\\u1ecb \\u0111\\u1ee9ng h\\u00ecnh */\\n.wp-block-search__button {\\n    white-space: nowrap !important; /* Ch\\u1eef ph\\u1ea3i n\\u1eb1m tr\\u00ean 1 h\\u00e0ng */\\n    min-width: 60px !important;    /* \\u0110\\u1ed9 r\\u1ed9ng t\\u1ed1i thi\\u1ec3u cho n\\u00fat */\\n    padding: 0 15px !important;\\n}\\n\\n/* Ch\\u1ec9nh l\\u1ea1i \\u00f4 nh\\u1eadp cho c\\u00e2n \\u0111\\u1ed1i */\\n.wp-block-search__input {\\n    flex-grow: 1 !important;\\n    min-width: 0 !important; /* \\u0110\\u1ec3 n\\u00f3 kh\\u00f4ng \\u0111\\u1ea9y n\\u00fat ra ngo\\u00e0i */\\n}\\n/* 1. \\u00c9p chi\\u1ec1u cao c\\u1ed1 \\u0111\\u1ecbnh cho khung s\\u1ea3n ph\\u1ea9m */\\n.woocommerce ul.products li.product {\\n    display: flex;\\n    flex-direction: column;\\n    background: #fff;\\n    padding: 15px;\\n    border: 1px solid #eee;\\n    border-radius: 8px;\\n    height: 100%;\\n}\\n\\n/* 2. \\u00c9p \\u1ea3nh s\\u1ea3n ph\\u1ea9m b\\u1eb1ng nhau v\\u00e0 kh\\u00f4ng b\\u1ecb m\\u00e9o */\\n.woocommerce ul.products li.product img {\\n    height: 200px !important; /* B\\u1ea1n c\\u00f3 th\\u1ec3 ch\\u1ec9nh s\\u1ed1 n\\u00e0y t\\u00f9y \\u00fd */\\n    object-fit: contain !important; \\n    margin-bottom: 15px;\\n}\\n\\n/* 3. \\u00c9p t\\u00ean s\\u1ea3n ph\\u1ea9m lu\\u00f4n chi\\u1ebfm 2 d\\u00f2ng (\\u0111\\u1ec3 kh\\u00f4ng b\\u1ecb l\\u1ec7ch gi\\u00e1) */\\n.woocommerce ul.products li.product .woocommerce-loop-product__title {\\n    min-height: 40px; \\n    line-height: 20px;\\n    margin-bottom: 10px;\\n    display: -webkit-box;\\n    -webkit-line-clamp: 2;\\n    -webkit-box-orient: vertical;\\n    overflow: hidden;\\n}\\n\\n/* 4. \\u0110\\u1ea9y n\\u00fat Add to cart xu\\u1ed1ng t\\u1eadn c\\u00f9ng cho th\\u1eb3ng h\\u00e0ng */\\n.woocommerce ul.products li.product .button {\\n    margin-top: auto !important;\\n    align-self: center;\\n}\\n/* \\u00c9p thanh ch\\u1ee9a logo gi\\u00e3n s\\u00e1t l\\u1ec1 tr\\u00e1i m\\u00e0n h\\u00ecnh */\\n.site-header .ast-container {\\n    max-width: 100% !important;\\n    padding-left: 15px !important;\\n}\\n.main-header-bar-wrap {\\n    max-width: 100% !important;\\n}\\n\\n\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-05-14 13:45:11\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '243e3763-7aa7-47ea-b90d-b080171f0d96', '', '', '2026-05-14 13:45:11', '2026-05-14 13:45:11', '', 0, 'http://localhost/BTL/?p=690', 0, 'customize_changeset', '', 0),
